BlocklyGamesMsg["Movie.helpText1"] = "השתמש בצורות פשוטות בשביל לצייר איש.";
BlocklyGamesMsg["Movie.helpText2a"] = "השלב הזה הוא סרט. המטרה שלך היא להזיז את היד של האיש לרוחב המסך. לחץ על כפתור ה־play כדי לצפות בו.";
BlocklyGamesMsg["Movie.helpText2b"] = "כאשר הסרט מתנגן, הערך של הבלוק ‚time’ עולה מ־0 ל־100. מאחר שהמטרה שמיקום ה־y של היד יתחיל מ־0 וימשיך עד 100, זה אמור להיות קל.";
BlocklyGamesMsg["Movie.helpText3"] = "ערך הבלוק 'time' עולה מ 0 ל 100. אבל הפעם המטרה שמיקום ה y של היד השניה יתחיל מ 100 וירד ל 0. האם תוכל למצוא שיטה מתמטית פשוטה שמחליפה את הכיוונים?";
BlocklyGamesMsg["Movie.helpText4"] = "השתמש במה שלמדת בשלב הקודם כדי ליצור רגלים מצטלבות";
BlocklyGamesMsg["Movie.helpText5"] = "הנוסחה המתמטית עבור היד מורכבת. הינה התשובה:";
BlocklyGamesMsg["Movie.helpText6"] = "תן לאיש מספר ידיים.";
BlocklyGamesMsg["Movie.helpText7"] = "השתמש בבלוק 'if' כדי לצייר ראש קטן לחצי הראשון של הסרט. לאחר מכן, צייר ראש גדול לחצי השני של הסרט.";
