BlocklyGamesMsg["Music.helpUseFunctions"] = "הפתרון שלך עובד, אבל אפשר להשתפר. יש השתמש בפונקציות כדי לצמצם את כמות הקוד החוזר על עצמו.";
BlocklyGamesMsg["Music.helpUseInstruments"] = "המוזיקה תשמע טוב יותר אם תשתמש בכלים שונים בכל בלוק";
BlocklyGamesMsg["Music.helpText1"] = "נגן את 4 התווים הראשונים של אחינו הנהג";
BlocklyGamesMsg["Music.helpText2a"] = "'פונקציה' מאפשרת לך ליצור קבוצה מכמה בלוקים ביחד, כך שהם רצים אחד אחרי השני.";
BlocklyGamesMsg["Music.helpText2b"] = "צור פונקציה כדי לנגן את 4 התווים הראשונים של אחינו הנהג. הרץ את הפונקציה הזאת פעמיים. אל תוסיף בלוקים חדשים של תווים.";
BlocklyGamesMsg["Music.helpText3"] = "צור פונקציה שניה לחלק הבא של השיר אחינו הנהג. התו האחרון ארוך יותר";
BlocklyGamesMsg["Music.helpText4"] = "צור פונקציה שלישית לחלק הבא של השיר אחינו הנהג. 4 התווים הראשונים הם קצרים יותר";
BlocklyGamesMsg["Music.helpText5"] = "להשלים את הנעימה ‚אחינו הנהג’.";
BlocklyGamesMsg["Music.helpText6a"] = "הלבנה החדשה הזאת מאפשרת לך להחליף כלי נגינה.";
BlocklyGamesMsg["Music.helpText6b"] = "נגן את המנגינה שלך עם כינור.";
BlocklyGamesMsg["Music.helpText7a"] = "לבנה חדשה זו מוסיפה השהיה שקטה.";
BlocklyGamesMsg["Music.helpText7b"] = "ליצור לבנת התחלה שנייה שבה שתי לבני השהיה, לאחר מכן יתנגן ‚אחינו הנהג’.";
BlocklyGamesMsg["Music.helpText8"] = "כל לבנת התחלה אמורה לנגן את ‚אחינו הנהג’ פעמיים.";
BlocklyGamesMsg["Music.helpText9"] = "עליך ליצור ארבע קוביות התחלה שכל אחת מהן מנגנת את ‚אחינו הנהג’ פעמיים. יש להוסיף את המספר הנכון של קוביות ההשהיה.";
BlocklyGamesMsg["Music.helpCanon"] = "A canon, like Frère Jacques, but on a new theme. Each voice enters one bar after the previous one. While a voice waits for its entry, and after it finishes, it tolls a bell: a half rest followed by C4. Record the theme as a procedure and call it from all four start blocks. Three or more voices should use different instruments.";  // untranslated
BlocklyGamesMsg["Music.helpCallResponse"] = "A conversation between four instruments. Put your four start blocks in order - trumpet (call), violin (answer), banjo (chatter) and piano (bass) - each looping its own short phrase. Every voice uses a different rhythm: quarters and halves, slow halves down low, and quick eighth notes. Use at least three different instruments, then let the parts trade calls and responses.";  // untranslated
BlocklyGamesMsg["Music.helpRound"] = "A two-voice round. The second voice waits two beats, then plays the same eight notes as the first. Use a procedure so the tune is written once.";  // untranslated
BlocklyGamesMsg["Music.helpWaltz"] = "A waltz in three-four time: three voices play a melody, a bass line on C and G, and a chord pattern. Repeat short patterns with loops.";  // untranslated
BlocklyGamesMsg["Music.helpChase"] = "A chase in eighth notes: three voices play the same rising phrase, each starting half a beat after the previous one.";  // untranslated
BlocklyGamesMsg["Music.helpSyncopation"] = "Syncopation: put the melody on the off-beats with quarter rests, while the bass and chord voices keep a steady pulse.";  // untranslated
BlocklyGamesMsg["Music.helpArpeggio"] = "An arpeggio study for four voices: broken chords ripple upward while the lower voices hold the harmony.";  // untranslated
BlocklyGamesMsg["Music.helpLullaby"] = "A lullaby for three voices: a gentle melody with rests, a rocking bass, and a soft harmony. Keep every note half a beat long.";  // untranslated
BlocklyGamesMsg["Music.helpRoundThree"] = "A three-voice round: voices enter one beat apart and play the same eight-note phrase.";  // untranslated
BlocklyGamesMsg["Music.helpFanfare"] = "A fanfare for four voices: a bright repeated call, a harmony a third below, a steady bass, and an echo of the call one beat later.";  // untranslated
BlocklyGamesMsg["Music.helpText10"] = "באפשרותך להלחין כל מה שבא לך. יש לך מגוון ענק של קוביות חדשות שמחכות לך לחקור אותן. באנו לבלות!";
BlocklyGamesMsg["Music.helpText10Reddit"] = "השתמש בכפתור 'צפיה בגלריה' כדי לצפות בשירים של משתמש אחרים. אם הלחנת משהו מעניין, השתמש בכפתור 'שליחה לגלריה' לפרסם אותו";
BlocklyGamesMsg["Pond.scanTooltip"] = "סרוק אם ישנם אויבים. ציין כיוון (0-360). קבל בחזרה את המרחק לאויב הקרוב ביותר בכיוון המבוקש. מחזיר Infinity אם אין אויב בכיוון המבוקש";
BlocklyGamesMsg["Pond.cannonTooltip"] = "בצע יריה מהתותח. ציין כיוון (0-360) וטווח (0-70).";
BlocklyGamesMsg["Pond.swimTooltip"] = "לשחות קדימה. נא לציין כיוון (0-360).";
BlocklyGamesMsg["Pond.stopTooltip"] = "להפסיק לשחות. השחקן יאט עד לעצירה.";
BlocklyGamesMsg["Pond.healthTooltip"] = "החזרת מצב הבריאות הנוכחי של השחקן (0 - מת, 100 - בריא).";
BlocklyGamesMsg["Pond.speedTooltip"] = "החזרת המהירות הנוכחית של השחקן (0 - עוצר, 100 - מהירות מלאה).";
BlocklyGamesMsg["Pond.locXTooltip"] = "החזרת נקודת הציון של השחקן בציר X‏ (0 - קצה שמאלי, 100 - קצה ימני).";
BlocklyGamesMsg["Pond.locYTooltip"] = "החזרת נקודת הציון של השחקן בציר Y‏ (0 - תחתית, 100 - ראש).";
BlocklyGamesMsg["Pond.logTooltip"] = "מדפיס מספר למסוף של הדפדפן שלך.";
