BlocklyGamesMsg["Pond.helpPatrol"] = "This opponent patrols along your row.  A cannon shot takes time to fly, so aiming at where the enemy is now lands behind it.  Use 'scan' to measure the distance, close in, then fire with that distance as the range.  On the last level the enemy fires back - don't just sit there.";  // untranslated
BlocklyGamesMsg["Pond.helpAdvanced"] = "A harder battle: several enemies at once. Read the battlefield, keep moving so you are not an easy target, and use 'scan', 'swim' and 'cannon' together. Some enemies shoot back.";  // untranslated
BlocklyGamesMsg["Pond.helpUseScan"] = "הפתרון שלך עובד, אבל אפשר להשתפר. נא להשתמש ב‚סריקה’ כדי להגיד לתותח כמה רחוק לירות.";
BlocklyGamesMsg["Pond.helpText1"] = "השתמש בפקודה 'cannon' כדי לפגוע במטרה. הפרמטר הראשון זו הזווית, השני זה הטווח. מצא את השילוב הנכון";
BlocklyGamesMsg["Pond.helpText2"] = "המטרה צריכה להיפגע כמה פעמים. השתמש בלולאת 'while (true)' כדי לבצע את הפעולה עד אין סוף.";
BlocklyGamesMsg["Pond.helpText3a"] = "היריב הזה זז מצד לצד מה שמקשה על פגיעה זו. הביטוי 'scan' מחזיר את הטווח המדוייק ליריב בכיוון מסויים";
BlocklyGamesMsg["Pond.helpText3b"] = "הטווח הזה הוא בדיוק מה שהפקודה 'canon' צריכה כדי לירות באופן מדוייק";
BlocklyGamesMsg["Pond.helpText4"] = "היריב הזה הוא רחוק מידי מכדי להשתמש בתותח (שהטווח שלו מוגבל ל 70 מטר). במקום זה, השתמש בפקודה 'swim' כדי להתחיל לשחות לכיוון היריב ולהתנגש בו.";
BlocklyGamesMsg["Pond.helpText5"] = "גם היריב הזה רחוק מדי מכדי להשתמש בתותח. אבל אתה חלש מידי כדי לשרוד התנגשות. תשחה לכיוון היריב כאשר המיקום האופקי שלך קטן מ 50. לאחר מכן השתמש ב stop ואז השתמש בתותח.";
BlocklyGamesMsg["Pond.helpText6"] = "היריב כבר יזוז עד הפגיעה. תשחה לכיוון שלו אם הוא מחוץ לטווח (70 מטר).";
