BlocklyGamesMsg["AI.help1"] = "There are only 4 examples — not enough. Choose <b>Class A</b>, click 2–3 times on the left, then <b>Class B</b> and click 2–3 times on the right. Press <b>Train</b>, then <b>Test</b>.";  // untranslated
BlocklyGamesMsg["AI.help2"] = "Six examples give a rough horizontal boundary. Blue A belongs below the line y = 0, orange B above it. Add 2–3 examples of each class near the boundary. With k = 1 the nearest example decides.";  // untranslated
BlocklyGamesMsg["AI.help3"] = "Four diagonal examples leave gaps. Blue A belongs below the line x + y = 0, orange B above it. Add 3–4 points on both sides, spread across the plot.";  // untranslated
BlocklyGamesMsg["AI.help4"] = "Two examples are labelled incorrectly: an orange triangle in the blue area and a blue circle in the orange area. Switch to <b>Erase</b> and remove them.";  // untranslated
BlocklyGamesMsg["AI.help5"] = "The labels are noisy. With k = 1 the machine copies every mistake. Raise k to 5–7 so a majority of neighbours decides.";  // untranslated
BlocklyGamesMsg["AI.help6"] = "Only 8 examples for a circle. Add points around the whole circle, especially where the machine is wrong.";  // untranslated
BlocklyGamesMsg["AI.help7"] = "Class A is rare. Add 5–8 blue points on the left, otherwise the rare class barely affects the answer.";  // untranslated
BlocklyGamesMsg["AI.help8"] = "XOR: the classes alternate. One neighbour memorises every corner; try k = 3 or 5 to smooth the boundary.";  // untranslated
BlocklyGamesMsg["AI.help9"] = "A circle. With k = 1 the boundary follows every point; add examples around the circle and try k = 3–5.";  // untranslated
BlocklyGamesMsg["AI.help10"] = "A ring. Both the inner and outer edges matter. Cover them with examples; too large k blurs the ring.";  // untranslated
BlocklyGamesMsg["AI.help11"] = "Two moons. The boundary is curved and close to itself. Start with k = 3; add points at the ends if errors remain.";  // untranslated
BlocklyGamesMsg["AI.help12"] = "A checkerboard. Small k follows the squares, large k blurs them. Compare k = 1, 3 and 5.";  // untranslated
BlocklyGamesMsg["AI.help13"] = "A spiral. Add examples along both arms; k = 1 memorises noise, k = 3–5 generalises.";  // untranslated
BlocklyGamesMsg["AI.help14"] = "Budget: at most 10 examples. Spread them along the diagonal; one or two points per class can beat ten random ones.";  // untranslated
BlocklyGamesMsg["AI.help15"] = "Final: a noisy spiral. Find and erase wrong labels, add points in problem areas, then tune k.";  // untranslated
BlocklyGamesMsg["AI.howTitle"] = "How does it work?";  // untranslated
BlocklyGamesMsg["AI.howBody"] = "The machine does not know the rule. It only sees the examples you give it. To classify a new point it finds the k nearest examples and picks the class that appears most often among them.<ul><li>Blue circles are class A; orange triangles are class B.</li><li>The tinted area is what the machine predicts.</li><li>Red crosses after Test are mistakes.</li><li>Small k follows individual examples; large k smooths the boundary.</li></ul>The goal is to generalise to new points, not to memorise the test.";  // untranslated
BlocklyGamesMsg["AI.kHelp"] = "Small k follows individual examples; large k smooths the boundary.";  // untranslated
